from duration import parse_duration
valid = {
 "1h30m": 5400, " 2d 4h ": 187200, "1.5h": 5400, "1w2d3h4m5s": 788645,
 "1:02:03": 3723, "-45s": -45, "0": 0, "1.5m": 90, "0.1h": 360,
 "1h 30m": 5400, "05m": 300, "90:00": 5400, "1:30": 90, "1:00:00": 3600,
 "-1h": -3600, "-1:30": -90, "-0s": 0, "0.25m": 15, "2w": 1209600,
 "1h 30m 5s": 5405, "0h":0, "0:00":0, "-0":0, "1.000s":1,
}
invalid = [".5h", "5.h", "30m1h", "1h1h", "1 h", "1h  30m", "0.3s", "1:60",
 "1:5", "", "   ", "5", "1.5", "+1h", "--1h", "-", "1:00:60", "1:000",
 "1h,30m", "1H", "1d1w", "00", "1..5h", "1h 30m1h", "1h\t30m"]
for s, e in valid.items():
    r = parse_duration(s)
    assert r == e, (s, r, e)
for s in invalid:
    try:
        r = parse_duration(s)
    except ValueError:
        pass
    else:
        raise AssertionError((s, r))
for x in [None, 1, b"1h", 1.5]:
    try:
        parse_duration(x)
    except TypeError:
        pass
    else:
        raise AssertionError(x)
print("all ok")
EOF
